def msg(lang, key, **kw):
    table = MESSAGES.get(lang) or MESSAGES["en"]
    text = table.get(key) or MESSAGES["en"].get(key) or key
    try:
        return text.format(**kw)
    except (KeyError, IndexError):
        return text


